def run_copilot_mode_comprehensive(
    files,
    analysis_modes: List[str] = None,
    enable_monitoring: bool = True,
    provider: str = "openai"
):
    """
    Ejecuta Copilot Mode con procesamiento integral.
    
    analysis_modes puede incluir:
    - "compliance": Análisis de compliance y riesgo
    - "due_diligence": Análisis de due diligence
    - "kpi_extraction": Extracción de KPIs y métricas
    - "monitoring": Monitoreo y alertas
    """
    accumulated_output = ""
    
    if not files:
        error_msg = "❌ No hay archivos subidos.\n\nArrastra tus PDFs al campo de archivos de Copilot."
        yield error_msg
        return
    
    if analysis_modes is None:
        analysis_modes = ["compliance", "kpi_extraction", "monitoring"]
    
    try:
        audit_logger.log(
            event_type="copilot",
            action="start_comprehensive_processing",
            resource="documents",
            result="started",
            metadata={
                "files_count": len(files),
                "analysis_modes": analysis_modes,
                "enable_monitoring": enable_monitoring,
                "provider": provider
            }
        )
        
        accumulated_output += "## 🚀 COPILOT MODE - Sistema Empresarial de Rendimiento Supremo\n\n"
        accumulated_output += f"**📄 Documentos**: {len(files)}\n"
        accumulated_output += f"**🔧 Modos de Análisis**: {', '.join(analysis_modes)}\n"
        accumulated_output += f"**🔔 Monitoreo**: {'✅ Activado' if enable_monitoring else '❌ Desactivado'}\n\n"
        accumulated_output += "---\n\n"
        yield accumulated_output
        
        # Crear instancia temporal de Copilot con el provider seleccionado
        temp_copilot = CopilotMode(config, provider=provider)
        
        # Procesamiento integral
        results = temp_copilot.process_documents_comprehensive(
            files=files,
            analysis_modes=analysis_modes,
            enable_monitoring=enable_monitoring
        )
        
        # Mostrar resultados de Compliance
        if "compliance" in analysis_modes and results.get("compliance_analysis"):
            comp = results["compliance_analysis"]
            accumulated_output += "### ⚖️ COMPLIANCE Y RIESGO CONTRACTUAL\n\n"
            accumulated_output += f"**Risk Score**: {comp.get('overall_risk_score', 0):.2f}/100\n"
            accumulated_output += f"**Estado de Cumplimiento**: {comp.get('compliance_status', 'unknown')}\n\n"
            
            # Cláusulas peligrosas
            if comp.get("dangerous_clauses"):
                accumulated_output += "#### ⚠️ Cláusulas Peligrosas Detectadas\n\n"
                for clause in comp["dangerous_clauses"][:10]:
                    risk_emoji = {"critical": "🔴", "high": "🟠", "medium": "🟡", "low": "🟢"}.get(
                        clause.get("risk_level", "medium"), "⚪"
                    )
                    accumulated_output += f"{risk_emoji} **{clause.get('clause_type', 'Unknown')}** ({clause.get('risk_level', 'N/A')})\n"
                    accumulated_output += f"   - {clause.get('description', '')[:200]}...\n"
                    accumulated_output += f"   - 📍 {clause.get('location', 'N/A')}\n"
                    accumulated_output += f"   - 💡 **Recomendación**: {clause.get('recommendation', 'N/A')[:150]}...\n"
                    if clause.get('potential_cost'):
                        accumulated_output += f"   - 💰 **Costo Potencial**: {clause.get('potential_cost')}\n"
                    accumulated_output += "\n"
            
            # Fechas críticas
            if comp.get("critical_dates"):
                accumulated_output += "#### 📅 Fechas Críticas\n\n"
                today = datetime.now().date()
                for date in comp["critical_dates"][:15]:
                    days = date.get("days_until", 999)
                    if days < 0:
                        urgency = "🔴 VENCIDA"
                    elif days <= 7:
                        urgency = "🔴 URGENTE"
                    elif days <= 30:
                        urgency = "🟠 PRÓXIMA"
                    else:
                        urgency = "🟢 Normal"
                    
                    accumulated_output += f"{urgency} **{date.get('date', 'N/A')}** ({days} días) - {date.get('description', '')[:100]}...\n"
                    accumulated_output += f"   - ⚠️ **Acción**: {date.get('action_required', 'N/A')[:100]}...\n\n"
            
            # Obligaciones legales
            if comp.get("legal_obligations"):
                accumulated_output += "#### ⚖️ Obligaciones Legales\n\n"
                for obligation in comp["legal_obligations"][:10]:
                    status_emoji = {
                        "overdue": "🔴",
                        "pending": "🟡",
                        "in_progress": "🟠",
                        "completed": "✅"
                    }.get(obligation.get("compliance_status", "pending"), "⚪")
                    accumulated_output += f"{status_emoji} **{obligation.get('obligation_type', 'Unknown')}**\n"
                    accumulated_output += f"   - 📋 {obligation.get('description', '')[:200]}...\n"
                    accumulated_output += f"   - 👤 Responsable: {obligation.get('responsible_party', 'N/A')}\n"
                    if obligation.get('deadline'):
                        accumulated_output += f"   - ⏰ Deadline: {obligation.get('deadline')}\n"
                    accumulated_output += "\n"
            
            # Costos ocultos
            if comp.get("hidden_costs"):
                accumulated_output += "#### 💰 Costos Ocultos Detectados\n\n"
                for cost in comp["hidden_costs"][:10]:
                    accumulated_output += f"💸 **{cost.get('cost_type', 'Unknown')}**\n"
                    if cost.get('amount'):
                        accumulated_output += f"   - 💵 Monto: {cost.get('amount')}\n"
                    accumulated_output += f"   - 📝 {cost.get('description', '')[:200]}...\n"
                    if cost.get('trigger_conditions'):
                        accumulated_output += f"   - ⚡ Se activa cuando: {', '.join(cost['trigger_conditions'][:3])}\n"
                    accumulated_output += "\n"
            
            accumulated_output += "---\n\n"
            yield accumulated_output
        
        # Mostrar resultados de Due Diligence
        if "due_diligence" in analysis_modes and results.get("due_diligence"):
            dd = results["due_diligence"]
            accumulated_output += "### 🔍 ANÁLISIS DE DUE DILIGENCE (M&A)\n\n"
            
            if dd.get("executive_summary"):
                accumulated_output += "#### 📄 Resumen Ejecutivo\n\n"
                accumulated_output += f"{dd['executive_summary']}\n\n"
            
            risk_assessment = dd.get("risk_assessment", {})
            if risk_assessment:
                overall_risk = risk_assessment.get("overall_risk", "unknown")
                risk_emoji = {"critical": "🔴", "high": "🟠", "medium": "🟡", "low": "🟢"}.get(overall_risk, "⚪")
                accumulated_output += f"#### {risk_emoji} Evaluación de Riesgo\n\n"
                accumulated_output += f"- **Riesgo General**: {overall_risk}\n"
                accumulated_output += f"- **Issues Críticos**: {risk_assessment.get('critical_issues_count', 0)}\n"
                accumulated_output += f"- **Riesgos Altos**: {risk_assessment.get('high_risk_issues_count', 0)}\n\n"
            
            if dd.get("findings"):
                accumulated_output += "#### 🔎 Hallazgos\n\n"
                for finding in dd["findings"][:15]:
                    severity_emoji = {
                        "critical": "🔴", "high": "🟠", "medium": "🟡", "low": "🟢"
                    }.get(finding.get("severity", "medium"), "⚪")
                    accumulated_output += f"{severity_emoji} **{finding.get('finding_type', 'Unknown').upper()}** - {finding.get('severity', 'N/A')}\n"
                    accumulated_output += f"   - {finding.get('description', '')[:250]}...\n"
                    accumulated_output += f"   - 📍 {finding.get('location', 'N/A')}\n"
                    accumulated_output += f"   - 💡 **Recomendación**: {finding.get('recommendation', 'N/A')[:150]}...\n"
                    if finding.get('financial_impact'):
                        accumulated_output += f"   - 💰 **Impacto Financiero**: {finding.get('financial_impact')}\n"
                    accumulated_output += "\n"
            
            if dd.get("recommendations"):
                accumulated_output += "#### 💡 Recomendaciones\n\n"
                for i, rec in enumerate(dd["recommendations"][:10], 1):
                    accumulated_output += f"{i}. {rec}\n"
                accumulated_output += "\n"
            
            accumulated_output += "---\n\n"
            yield accumulated_output
        
        # Mostrar resultados de KPI Extraction
        if "kpi_extraction" in analysis_modes and results.get("kpi_extraction"):
            kpi = results["kpi_extraction"]
            accumulated_output += "### 📊 EXTRACCIÓN DE KPIs Y MÉTRICAS\n\n"
            accumulated_output += f"**✅ Listo para exportar**: Excel, Dashboards, CRM\n\n"
            
            if kpi.get("kpis"):
                accumulated_output += "#### 📈 KPIs Extraídos\n\n"
                for kpi_item in kpi["kpis"][:20]:
                    accumulated_output += f"- **{kpi_item.get('kpi_name', 'Unknown')}**: {kpi_item.get('value', 'N/A')} {kpi_item.get('unit', '')}\n"
                    accumulated_output += f"  - Período: {kpi_item.get('period', 'N/A')}\n"
                    if kpi_item.get('context'):
                        accumulated_output += f"  - Contexto: {kpi_item.get('context', '')[:100]}...\n"
                    accumulated_output += "\n"
            
            if kpi.get("structured_data"):
                accumulated_output += "#### 📋 Datos Estructurados\n\n"
                structured = kpi["structured_data"]
                if structured.get("contracts"):
                    accumulated_output += f"**Contratos**: {len(structured['contracts'])} encontrados\n"
                if structured.get("payments"):
                    accumulated_output += f"**Pagos**: {len(structured['payments'])} encontrados\n"
                if structured.get("clients"):
                    accumulated_output += f"**Clientes**: {len(structured['clients'])} encontrados\n"
                accumulated_output += "\n"
            
            accumulated_output += "💾 **Exportación**: Usa el botón 'Exportar a Excel' para descargar los datos\n\n"
            accumulated_output += "---\n\n"
            yield accumulated_output
        
        # Mostrar alertas de monitoreo
        if enable_monitoring and results.get("monitoring"):
            monitoring = results["monitoring"]
            if monitoring.get("alerts_generated", 0) > 0:
                accumulated_output += "### 🔔 ALERTAS Y MONITOREO\n\n"
                accumulated_output += f"**Alertas Generadas**: {monitoring.get('alerts_generated', 0)}\n\n"
                
                for alert in monitoring.get("alerts", [])[:10]:
                    severity_emoji = {
                        "critical": "🔴", "high": "🟠", "medium": "🟡", "low": "🟢", "info": "ℹ️"
                    }.get(alert.get("severity", "medium"), "⚪")
                    accumulated_output += f"{severity_emoji} **{alert.get('alert_type', 'Unknown')}** - {alert.get('severity', 'N/A')}\n"
                    accumulated_output += f"   - {alert.get('message', '')[:200]}...\n"
                    accumulated_output += f"   - 📄 {alert.get('document_id', 'N/A')}\n\n"
                
                accumulated_output += "---\n\n"
                yield accumulated_output
        
        accumulated_output += "\n✅ **Procesamiento Copilot completado exitosamente!**\n"
        
        audit_logger.log(
            event_type="copilot",
            action="complete_comprehensive_processing",
            resource="documents",
            result="success",
            metadata={"files_count": len(files)}
        )
        
    except Exception as e:
        error_msg = f"Error en Copilot Mode: {str(e)}"
        audit_logger.log(
            event_type="error",
            action="copilot",
            resource="documents",
            result="error",
            metadata={"error": str(e)}
        )
        accumulated_output += f"\n❌ **Error**: {error_msg}\n"
    
    yield accumulated_output


def run_copilot_compliance_analysis_streaming(files, provider: str = "openai"):
    """Ejecuta análisis de compliance y riesgo contractual con streaming."""
    accumulated_output = ""
    
    if not files:
        yield "❌ No hay archivos subidos."
        return
    
    try:
        accumulated_output += "## ⚖️ ANÁLISIS DE COMPLIANCE Y RIESGO CONTRACTUAL\n\n"
        accumulated_output += "🔍 Analizando documentos...\n\n"
        yield accumulated_output
        
        temp_copilot = CopilotMode(config, provider=provider)
        results = temp_copilot.analyze_contract_compliance(files)
        
        accumulated_output += f"**Risk Score**: {results.get('overall_risk_score', 0):.2f}/100\n"
        accumulated_output += f"**Estado**: {results.get('compliance_status', 'unknown')}\n\n"
        
        # Cláusulas peligrosas
        if results.get("dangerous_clauses"):
            accumulated_output += "### ⚠️ Cláusulas Peligrosas Detectadas\n\n"
            for clause in results["dangerous_clauses"][:15]:
                risk_emoji = {"critical": "🔴", "high": "🟠", "medium": "🟡", "low": "🟢"}.get(
                    clause.get("risk_level", "medium"), "⚪"
                )
                accumulated_output += f"{risk_emoji} **{clause.get('clause_type', 'Unknown')}** ({clause.get('risk_level', 'N/A')})\n"
                accumulated_output += f"   - {clause.get('description', '')[:300]}...\n"
                accumulated_output += f"   - 📍 {clause.get('location', 'N/A')}\n"
                accumulated_output += f"   - 💡 Recomendación: {clause.get('recommendation', 'N/A')[:200]}...\n"
                if clause.get('potential_cost'):
                    accumulated_output += f"   - 💰 Costo Potencial: {clause.get('potential_cost')}\n"
                accumulated_output += "\n"
            yield accumulated_output
        
        # Fechas críticas
        if results.get("critical_dates"):
            accumulated_output += "### 📅 Fechas Críticas\n\n"
            sorted_dates = sorted(results["critical_dates"], key=lambda x: x.get("days_until", 999))
            for date in sorted_dates[:15]:
                days = date.get("days_until", 999)
                urgency = "🔴 VENCIDA" if days < 0 else "🔴 URGENTE" if days <= 7 else "🟠 PRÓXIMA" if days <= 30 else "🟢 Normal"
                accumulated_output += f"{urgency} **{date.get('date', 'N/A')}** ({days} días)\n"
                accumulated_output += f"   - {date.get('description', '')[:150]}...\n"
                accumulated_output += f"   - ⚠️ Acción: {date.get('action_required', 'N/A')[:150]}...\n\n"
            yield accumulated_output
        
        # Obligaciones legales
        if results.get("legal_obligations"):
            accumulated_output += "### ⚖️ Obligaciones Legales\n\n"
            for obligation in results["legal_obligations"][:15]:
                status_emoji = {
                    "overdue": "🔴", "pending": "🟡", "in_progress": "🟠", "completed": "✅"
                }.get(obligation.get("compliance_status", "pending"), "⚪")
                accumulated_output += f"{status_emoji} **{obligation.get('obligation_type', 'Unknown')}**\n"
                accumulated_output += f"   - {obligation.get('description', '')[:250]}...\n"
                accumulated_output += f"   - 👤 Responsable: {obligation.get('responsible_party', 'N/A')}\n"
                if obligation.get('deadline'):
                    accumulated_output += f"   - ⏰ Deadline: {obligation.get('deadline')}\n"
                accumulated_output += "\n"
            yield accumulated_output
        
        # Costos ocultos
        if results.get("hidden_costs"):
            accumulated_output += "### 💰 Costos Ocultos Detectados\n\n"
            for cost in results["hidden_costs"][:15]:
                accumulated_output += f"💸 **{cost.get('cost_type', 'Unknown')}**\n"
                if cost.get('amount'):
                    accumulated_output += f"   - 💵 Monto: {cost.get('amount')}\n"
                accumulated_output += f"   - {cost.get('description', '')[:200]}...\n"
                if cost.get('trigger_conditions'):
                    accumulated_output += f"   - ⚡ Se activa: {', '.join(cost['trigger_conditions'][:3])}\n"
                accumulated_output += "\n"
            yield accumulated_output
        
    except Exception as e:
        accumulated_output += f"\n❌ Error: {str(e)}\n"
        yield accumulated_output


