                                result_email = leads_mode.send_message_to_lead(
                                    lead.lead_id,
                                    "email",
                                    subject=subject if not auto_gen else None,
                                    content=content if not auto_gen else "",
                                    auto_generate=auto_gen
                                )
                                
                                result_whatsapp = leads_mode.send_message_to_lead(
                                    lead.lead_id,
                                    "whatsapp",
                                    content=content if not auto_gen else "",
                                    auto_generate=auto_gen
                                )
                                
