                def generate_brief(topic, depth):
                    if not research_action_agent:
                        return "❌ Research & Action Agent no está habilitado.", None
                    
                    if not topic or not topic.strip():
                        return "⚠️ Por favor, ingresa un tema de investigación.", None
                    
