                        provider=provider,
                        model=fullstack_text_to_action.config.agentic_model or "gpt-4o",
                        temperature=0.2,
                        api_key=fullstack_text_to_action.config.openai_api_key if provider == "openai" else fullstack_text_to_action.config.anthropic_api_key,
                        max_tokens=8000,
